import serial
import time

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
READ_INTERVAL_SECONDS = 0.5

def open_serial_port(port_path, baud_rate):
    """Open and return a serial port with the given settings."""
    # pyserial makes the UART link available to the Raspberry Pi
    return serial.Serial(port_path, baud_rate, timeout=1)

def read_serial_line(serial_connection):
    """Read one line from the serial port, or None on timeout."""
    # Read a fixed number of bytes and decode them
    raw_bytes = serial_connection.read(1024)
    if not raw_bytes:
        return None
    return raw_bytes.decode("utf-8", errors="ignore").strip()

def main():
    """Exchange data with the connected device in a loop."""
    serial_connection = None
    try:
        # Open the serial port and exchange data
        serial_connection = open_serial_port(SERIAL_PORT, BAUD_RATE)
        while True:
            received_line = read_serial_line(serial_connection)
            if received_line is not None:
                print("Device says:", received_line)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Stopping data exchange")
    finally:
        # Always release the serial port
        if serial_connection is not None:
            serial_connection.close()

if __name__ == "__main__":
