# UART data exchange loop for a Raspberry Pi
# Reads a serial device and prints each line received
# Uses pyserial to talk to a connected UART peripheral
import serial
import time

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
RETRY_DELAY = 1.0


def open_serial_port(port_path, baud_rate):
    """Open and return a serial port with the given settings."""
    # pyserial makes the UART device available to the Pi
    return serial.Serial(port_path, baud_rate, timeout=1.0)


def read_valid_line(serial_connection):
    """Read one line from the serial port, rejecting garbage."""
    # Ignore any bytes until a newline arrives
    while True:
        received_bytes = serial_connection.readline()
        if not received_bytes:
            return None
        if received_bytes == "\n":
            return received_bytes.decode("ascii", errors="replace")


def main():
    """Exchange data with the connected device in a loop."""
    serial_connection = None
    try:
        # Open the serial port and prepare to read
        serial_connection = open_serial_port(SERIAL_PORT, BAUD_RATE)
        print("Serial device opened")
        while True:
            received_line = read_valid_line(serial_connection)
            if received_line is not None:
                print("Device said:", received_line)
            time.sleep(RETRY_DELAY)
    except serial.SerialException as serial_error:
        # Report a serial port failure
        print("Serial error:", serial_error)
    except KeyboardInterrupt:
        print("Stopping data exchange")
    finally:
        # Always release the serial hardware
        if serial_connection is not None:
            serial_connection.close()


if __name__ == "__main__":
    main()

