from gpiozero import OutputDevice
import time

# BCM pin assignments for the digital outputs
OUTPUT_PINS = [4, 17, 18, 22, 23, 24, 25, 27]

def build_output_device(pin):
    """Create a gpiozero OutputDevice for one GPIO pin."""
    # Attempt to create the output device; return None on failure
    device = OutputDevice(pin)
    if not device.is_active:
        print("Warning: output device on pin %s failed to initialise" % pin)
        return None
    return device

def apply_state(device, state):
    """Apply a boolean state to a gpiozero OutputDevice."""
    # Set the pin to the requested state
    device.value = state

def report_state(state_list):
    """Print the current state of every output device."""
    # Walk the list and report each device's current state
    for device in state_list:
        if device is not None:
            print("GPIO %s -> %s" % (device.pin, device.value))

def main():
    """Run the digital output control loop."""
    # Create an output device for each pin
    output_devices = []
    for pin in OUTPUT_PINS:
        device = build_output_device(pin)
        if device is None:
            return
        output_devices.append(device)
    try:
        # Toggle the outputs in a tight loop
        while True:
            # Set all outputs to HIGH
            for device in output_devices:
                apply_state(device, True)
            time.sleep(0.001)
            # Set all outputs to LOW
            for device in output_devices:
                apply_state(device, False)
            time.sleep(0.001)
    except KeyboardInterrupt:
        # Stop cleanly on interrupt
        print("Stopping digital output controller")
    finally:
        # Release all gpiozero resources
        for device in output_devices:
            device.close()

if __name__ == "__main__":
    main()

