def apply_fan_speed(fan_device, speed_value):
    """Apply a fan speed (0.0 to 1.0) to a PWM fan device."""
    fan_device.value = speed_value
    print("Fan set to", round(speed_value, 1), "%")


def read_cpu_temperature():
    """Read the CPU temperature from the Raspberry Pi."""
    cpu = CPUTemperature()
    return cpu.temperature


def determine_fan_speeds(cpu_temp, fan_devices):
    """Determine the desired fan speed for each PWM fan based on CPU temperature."""
    speeds = {}
    for fan_index, pin in FAN_PINS.items():
